def patch_file(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        text = f.read()

    # Find the start of tagReference or ensureCaretAtEnd
    pos_start = text.find(';const ensureCaretAtEnd=')
    if pos_start == -1:
        pos_start = text.find('const tagReference=async')
    if pos_start == -1:
        pos_start = text.find(',tagReference=async')

    pos_end = text.find(',B=e=>', pos_start)

    if pos_start == -1 or pos_end == -1:
        print(f"Error: Could not locate block in {filepath} (start={pos_start}, end={pos_end})")
        return False

    # Check prefix
    prefix = ';' if text[pos_start] == ';' else ''
    new_text = text[:pos_start] + prefix + replacement_code + text[pos_end:]

    with open(filepath, 'w', encoding='utf-8') as f:
        f.write(new_text)

    print(f"Successfully patched {filepath} (new length: {len(new_text)})")
    return True

